def move_groq_settings(apps, schema_editor):
    """Переносить Groq-ключі та промпти з налаштувань автопостингу в окремі конфіги уникалізації."""
    AutoPostConfig = apps.get_model('tasks', 'AutoPostConfig')
    AutoPostUniquenessConfig = apps.get_model('tasks', 'AutoPostUniquenessConfig')
    default_prompt = AutoPostUniquenessConfig._meta.get_field('prompt').default

    created = {}
    for autopost in AutoPostConfig.objects.exclude(groq_api_key__isnull=True).exclude(groq_api_key=''):
        key = (autopost.groq_api_key.strip(), autopost.groq_prompt or default_prompt)

        if key not in created:
            created[key] = AutoPostUniquenessConfig.objects.create(
                name="Groq" if not created else f"Groq {len(created) + 1}",
                api_key=key[0],
                prompt=key[1],
            )

        autopost.uniqueness_config = created[key]
        autopost.save(update_fields=['uniqueness_config'])


